import os
from subprocess import Popen, PIPE

from ..conf import settings
from ..utils import DEVNULL, memoize, cache
from .generic import Generic


class Bash(Generic):
    def app_alias(self, alias_name):
        prefix = ("TF_ALIAS={0}"
                  " alias {0}='PYTHONIOENCODING=utf-8"
                  " TF_CMD=$(thefuck $(fc -ln -1)) && "
                  " eval $TF_CMD").format(alias_name)

        if settings.alter_history:
            return prefix + " && history -s $TF_CMD'"
        return prefix + "'"

    def _parse_alias(self, raw_alias):
        key, val = raw_alias.replace('alias ', '', 1).split('=', 1)
        if (val[0] == '"' and val[-1] == '"') or (val[0] == "'" and val[-1] == "'"):
            val = val[1:-1]
        return key, val

    @memoize
    @cache('.bashrc', '.bash_profile')
    def get_aliases(self):
        bash_proc = Popen(['bash', '-ic', 'alias'],
                          stdout=PIPE, stderr=DEVNULL)
        parsed = []
        for line in bash_proc.stdout.read().decode('utf-8').split('\n'):
            if line and '=' in line:
                parsed.append(self._parse_alias(line))
        return dict(parsed)

    def _get_history_file_name(self):
        default_path = os.path.expanduser('~/.bash_history')
        return os.environ.get("HISTFILE", default_path)

    def _get_history_line(self, command_script):
        return u'{}\n'.format(command_script)

    def how_to_configure(self):
        if os.path.join(os.path.expanduser('~'), '.bashrc'):
            config_file = '~/.bashrc'
        elif os.path.join(os.path.expanduser('~'), '.bash_profile'):
            config_file = '~/.bashrc'
        else:
            config_file = 'bash config'
        return 'eval $(thefuck --alias)', config_file
